import { useCallback, useEffect, useState } from 'react';
import { Download, FileText, RefreshCw } from 'lucide-react';
import { api } from '../services/api';

interface ReportInfo {
  id: string;
  name: string;
  description: string;
  format: string;
  date_filter: boolean;
  rows: number | null;
  available: boolean;
}

interface Downloaded {
  id: string;
  name: string;
  filename: string;
  rows: number;
  at: string;
}

/** Reports are CSV files generated by the backend from the live database. */
export function ReportsPage() {
  const [reports, setReports] = useState<ReportInfo[]>([]);
  const [planId, setPlanId] = useState<string | null>(null);
  const [planWindow, setPlanWindow] = useState<[string, string] | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [range, setRange] = useState({ start: '', end: '' });
  const [history, setHistory] = useState<Downloaded[]>([]);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.listReports();
      setReports(data.reports || []);
      setPlanId(data.plan_id || null);
      setPlanWindow(data.plan_window || null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load reports');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const download = async (report: ReportInfo) => {
    setBusy(report.id);
    setError(null);
    try {
      const params = report.date_filter
        ? { start_date: range.start || undefined, end_date: range.end || undefined }
        : undefined;
      const { blob, filename, rows } = await api.downloadReport(report.id, params);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
      setHistory((h) => [{ id: report.id, name: report.name, filename, rows, at: new Date().toLocaleTimeString() }, ...h].slice(0, 10));
    } catch (err) {
      setError(`${report.name}: ${err instanceof Error ? err.message : 'download failed'}`);
    } finally {
      setBusy(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-secondary-900">Reports</h1>
          <p className="text-secondary-500">CSV exports generated by the backend from the current database</p>
        </div>
        <button className="btn-secondary" onClick={load} disabled={loading}>
          <RefreshCw className="w-4 h-4" />
          Refresh
        </button>
      </div>

      <div className="card p-4 text-sm text-secondary-600" data-testid="reports-plan">
        {planId
          ? <>Plan reports use the latest production plan <span className="font-medium text-secondary-900">{planId}</span>{planWindow ? ` (${planWindow[0]} to ${planWindow[1]})` : ''}.</>
          : 'No production plan yet: generate one on Production Planning to enable the plan reports.'}
        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span>Orders date filter (optional):</span>
          <input type="date" className="input w-auto" aria-label="Orders from" value={range.start} onChange={(e) => setRange({ ...range, start: e.target.value })} />
          <span>to</span>
          <input type="date" className="input w-auto" aria-label="Orders to" value={range.end} onChange={(e) => setRange({ ...range, end: e.target.value })} />
        </div>
      </div>

      {error && <div className="card p-4 text-sm text-danger-700 bg-danger-50">{error}</div>}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading && !reports.length && <div className="text-secondary-500">Loading reports...</div>}
        {reports.map((report) => (
          <div key={report.id} className="card p-4 flex flex-col gap-3" data-testid={`report-${report.id}`}>
            <div className="flex items-start gap-3">
              <div className="p-3 rounded-lg bg-primary-50 text-primary-600"><FileText className="w-5 h-5" /></div>
              <div className="min-w-0">
                <h4 className="font-medium text-secondary-900">{report.name}</h4>
                <p className="text-sm text-secondary-500 mt-1">{report.description}</p>
                {typeof report.rows === 'number' && (
                  <p className="text-xs text-secondary-400 mt-1">{report.rows.toLocaleString('en-US')} rows in database</p>
                )}
              </div>
            </div>
            <button
              className="btn-primary text-sm mt-auto"
              onClick={() => download(report)}
              disabled={!report.available || busy === report.id}
              title={report.available ? `Download ${report.name} (CSV)` : 'No data yet'}
            >
              <Download className="w-4 h-4" />
              {busy === report.id ? 'Preparing...' : report.available ? 'Download CSV' : 'No data yet'}
            </button>
          </div>
        ))}
      </div>

      {history.length > 0 && (
        <div className="card">
          <div className="p-4 border-b border-secondary-200">
            <h3 className="text-lg font-semibold text-secondary-900">Downloaded this session</h3>
          </div>
          <div className="table-container">
            <table className="table">
              <thead><tr><th>Report</th><th>File</th><th className="text-right">Rows</th><th>Time</th></tr></thead>
              <tbody>
                {history.map((h, i) => (
                  <tr key={`${h.filename}-${i}`}>
                    <td>{h.name}</td>
                    <td className="font-mono text-xs">{h.filename}</td>
                    <td className="text-right">{Number.isFinite(h.rows) ? h.rows.toLocaleString('en-US') : '-'}</td>
                    <td>{h.at}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
